html:
{%- import "costeo_yelke/templates/print/oc_yelke.html" as oc -%}
{#- Cotización.
    Página 1: la cotización (lo que tiene cantidad), totales, términos y firmas.
    Página 2 (solo si hay algo que mostrar), informativa, no suma al total:
      · Tallas extra: variantes de talla cuya cantidad aún no da el cliente.
        Con tabla por volumen sale su tabla; sin ella, su precio por pieza.
      · Precios por volumen de los productos cotizados.
    Diseño compartido: templates/print/oc_yelke.html -#}
{{ oc.estilos() }}
<style>
.yk-pagina { page-break-before: always; }
.yk-nota { font-size: 7.4pt; color: #777; margin: 0 0 2.5mm; }
.yk-talla { font-size: 7.4pt; color: #e65a0b; font-weight: 600; margin-top: 0.6mm; }
</style>
{{ oc.membrete_encabezado(doc, no_letterhead, print_settings, "Cotización") }}
<div class="pdf-container">
{{ oc.marca_borrador(doc) }}
{{ oc.datos(doc, {"etiqueta": "Cliente", "nombre": doc.customer_name or doc.party_name, "rfc": rfc_tercero("Customer", doc.party_name), "direccion": direccion_lineas(doc.customer_address)},
    [("Fecha de elaboración", fecha_corta(doc.transaction_date)),
     ("Vigente hasta", fecha_corta(doc.valid_till)),
     ("Moneda", doc.currency)]) }}

{{ oc.tabla_articulos(doc) }}
{{ oc.cierre(doc) }}

{#- ── Precio de una regla de volumen ── -#}
{%- macro precio_regla(rule, row) -%}
  {%- set precio_lista = row.get("price_list_rate") or row.get("rate") or 0 -%}
  {%- if rule.rate and rule.rate > 0 -%}
    {{ frappe.utils.fmt_money(rule.rate, currency=doc.currency) }}
  {%- elif rule.discount_percentage and rule.discount_percentage > 0 -%}
    {{ frappe.utils.fmt_money(precio_lista * (1 - rule.discount_percentage / 100), currency=doc.currency) }}
  {%- elif rule.discount_amount and rule.discount_amount > 0 -%}
    {{ frappe.utils.fmt_money([precio_lista - rule.discount_amount, 0] | max, currency=doc.currency) }}
  {%- else -%}
    —
  {%- endif -%}
{%- endmacro -%}

{#- ── Tablas de precios: filas seguidas con los mismos rangos comparten tabla; una fila
    sin rangos (solo_con_rangos=false) sale con su precio por pieza. Mismo estilo que
    la tabla de artículos de la cotización. ── -#}
{%- macro tablas_precios(filas, solo_con_rangos) -%}
{%- set grupos = [] -%}
{%- for row in filas -%}
    {%- set rules = frappe.get_all("Pricing Rule",
        filters={"item_code": row.item_code, "disable": 0, "selling": 1, "min_qty": [">", 0]},
        fields=["min_qty", "max_qty", "rate", "discount_percentage", "discount_amount"],
        order_by="min_qty asc") if row.item_code else [] -%}
    {%- if rules or not solo_con_rangos -%}
        {%- set ns = namespace(firma="", grupo=None) -%}
        {%- for rule in rules -%}{%- set ns.firma = ns.firma ~ (rule.min_qty|int) ~ "-" ~ ((rule.max_qty or 0)|int) ~ ";" -%}{%- endfor -%}
        {%- if grupos and grupos[-1].firma == ns.firma -%}{%- set ns.grupo = grupos[-1] -%}{%- endif -%}
        {%- if ns.grupo is none -%}
            {%- set ns.grupo = {"firma": ns.firma, "rangos": [], "filas": [], "img": false} -%}
            {%- for rule in rules -%}
                {%- set _ = ns.grupo.rangos.append(("{:,}".format(rule.min_qty|int) ~ "–" ~ "{:,}".format(rule.max_qty|int) ~ " pzas") if rule.max_qty and rule.max_qty > 0 else ("{:,}".format(rule.min_qty|int) ~ "+ pzas")) -%}
            {%- endfor -%}
            {%- set _ = grupos.append(ns.grupo) -%}
        {%- endif -%}
        {%- set img = imagen_articulo(row) -%}
        {%- if img -%}{%- set _ = ns.grupo.update({"img": true}) -%}{%- endif -%}
        {%- set _ = ns.grupo.filas.append({"row": row, "rules": rules, "img": img}) -%}
    {%- endif -%}
{%- endfor -%}
{%- for g in grupos %}
<table class="items-table">
    <thead>
        <tr>
            {% if g.img %}<th style="width:17mm"></th>{% endif %}
            <th>Artículo</th>
            {%- if g.rangos %}
            {%- for titulo in g.rangos %}<th class="text-right" style="width:24mm">{{ titulo }}</th>{%- endfor %}
            {%- else %}
            <th class="text-right" style="width:27mm">Precio por pieza</th>
            {%- endif %}
        </tr>
    </thead>
    <tbody>
        {%- for f in g.filas %}
        <tr>
            {% if g.img %}<td><div class="item-foto">{% if f.img %}<img src="{{ f.img }}" alt="">{% endif %}</div></td>{% endif %}
            <td>
                <div class="item-title">{{ f.row.item_name or f.row.item_code }}</div>
                <div class="item-code"><span class="k">Código de producto:</span> {{ f.row.item_code }}</div>
                {% if f.row.get("talla") %}<div class="yk-talla">Talla: {{ f.row.talla }}</div>{% endif %}
            </td>
            {%- if g.rangos %}
            {%- for rule in f.rules %}<td class="num"><b>{{ precio_regla(rule, f.row) }}</b></td>{%- endfor %}
            {%- else %}
            <td class="num"><b>{{ frappe.utils.fmt_money(f.row.rate, currency=doc.currency) }}</b></td>
            {%- endif %}
        </tr>
        {%- endfor %}
    </tbody>
</table>
{%- endfor %}
{%- endmacro -%}

{%- set extras = tallas_atipicas(doc) -%}
{%- set con_volumen = [] -%}
{%- for row in doc.items -%}
    {%- if row.item_code and row.item_code not in con_volumen and frappe.db.exists("Pricing Rule Item Code", {"item_code": row.item_code}) -%}
        {%- set _ = con_volumen.append(row.item_code) -%}
    {%- endif -%}
{%- endfor -%}
{% if extras or con_volumen %}
<div class="yk-pagina">
    {% if extras %}
    {{ oc.seccion("Tallas extra") }}
    <p class="yk-nota">Precio por pieza, sobre pedido. No incluido en el total.</p>
    {{ tablas_precios(extras, false) }}
    {% endif %}
    {% if con_volumen %}
    {{ oc.seccion("Precios por volumen · tallas regulares") }}
    <p class="yk-nota">Precio por pieza de las tallas regulares, según la cantidad total del pedido.</p>
    {%- set vistos = [] -%}
    {%- set filas = [] -%}
    {%- for row in doc.items -%}
        {%- if row.item_code in con_volumen and row.item_code not in vistos -%}
            {%- set _ = vistos.append(row.item_code) -%}{%- set _ = filas.append(row) -%}
        {%- endif -%}
    {%- endfor -%}
    {{ tablas_precios(filas, true) }}
    {% endif %}
</div>
{% endif %}
</div>
{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
